    @Override public boolean dispatchTouchEvent(MotionEvent event){if(fullscreen&&event.getActionMasked()==MotionEvent.ACTION_DOWN)handler.removeCallbacks(hideVideoControls);boolean handled=super.dispatchTouchEvent(event);if(fullscreen&&(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL))scheduleControlsHide();return handled;}
    private boolean allowed(){if(Build.VERSION.SDK_INT>=33)return checkSelfPermission(Manifest.permission.READ_MEDIA_VIDEO)==PackageManager.PERMISSION_GRANTED||(Build.VERSION.SDK_INT>=34&&checkSelfPermission(Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED)==PackageManager.PERMISSION_GRANTED);return checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED;}
    private void permission(boolean request){if(allowed()&&!request){scan();return;}if(!request){status.setText("Abra o menu ☰ para permitir vídeos ou escolher um arquivo.");return;}if(Build.VERSION.SDK_INT>=34)requestPermissions(new String[]{Manifest.permission.READ_MEDIA_VIDEO,Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED},PERMISSION);else requestPermissions(new String[]{Build.VERSION.SDK_INT>=33?Manifest.permission.READ_MEDIA_VIDEO:Manifest.permission.READ_EXTERNAL_STORAGE},PERMISSION);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==PERMISSION){if(allowed())scan();else{videos.clear();render();status.setText("Acesso não concedido. Use Menu → Abrir arquivo.");}}}
    private void scan(){final int generation=++scanGeneration;status.setText("Buscando vídeos…");scanner.execute(()->{try{List<VideoStore.Item> found=VideoStore.scan(this);runOnUiThread(()->{if(isDestroyed()||generation!=scanGeneration)return;videos.clear();videos.addAll(found);render();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&generation==scanGeneration){videos.clear();render();status.setText("Não foi possível listar os vídeos. Use o menu para permitir acesso ou abrir um arquivo.");}});}});}
    private void render(){if(adapter==null)return;visible.clear();for(VideoStore.Item item:videos)if(VideoText.matches(item.title,item.file,search.getText().toString()))visible.add(item);adapter.notifyDataSetChanged();status.setText(visible.size()+" de "+videos.size()+" vídeos"+(videos.isEmpty()?" • Menu → Abrir arquivo":""));}
    private void pickFile(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI,android.provider.DocumentsContract.buildDocumentUri("com.android.externalstorage.documents","primary:Movies"));try{leavingForPicker=true;startActivityForResult(intent,OPEN);}catch(ActivityNotFoundException e){leavingForPicker=false;Toast.makeText(this,"Nenhum seletor de arquivos disponível.",Toast.LENGTH_LONG).show();}}
    private VideoStore.Item selected(Uri uri){String title="Vídeo selecionado";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&c.getString(0)!=null)title=c.getString(0);}catch(Exception ignored){}return new VideoStore.Item(uri,title,title,0,0);}
    private void selectedFile(Uri uri){VideoStore.Item item=selected(uri);queue=new ArrayList<>(Collections.singletonList(item));queueIndex=0;pending=item;openPending();}
    private void openPending(){if(backgroundRestore!=null&&started&&music!=null){restoreBackground();return;}if(pending!=null&&started&&music!=null){VideoStore.Item item=pending;pending=null;long at=pendingPosition;pendingPosition=-1;if(at>=0){disableLoop(null);open(item,false,at);}else choose(item);}}
    private void receiveView(Intent intent){Uri uri=intent.getData();if(Intent.ACTION_VIEW.equals(intent.getAction())&&uri!=null&&("content".equalsIgnoreCase(uri.getScheme())||"file".equalsIgnoreCase(uri.getScheme()))){VideoBackgroundService.stopForMusic(this);handedOff=false;backgroundRestore=null;pendingPosition=intent.getLongExtra("onda_start_ms",-1);selectedFile(uri);}}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);receiveView(intent);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);leavingForPicker=false;if(result!=RESULT_OK||data==null||data.getData()==null)return;if(request==OPEN)selectedFile(data.getData());else if(request==SUBTITLE)loadSubtitle(data.getData());}
    private void open(VideoStore.Item item,boolean useSoftware){open(item,useSoftware,0);}
    private void open(VideoStore.Item item,boolean useSoftware,long startPosition){
        if(video==null||!started)return;if(music==null){pending=item;status.setText("Preparando áudio…");return;}
        VideoBackgroundService.stopForMusic(this);music.pause();if(!requestFocus())return;remember();handedOff=false;resumePosition=-1;handler.removeCallbacks(firstFrameCheck);framesSeen=false;
        if(current==null||!current.uri.equals(item.uri)){learningRate=1f;if(learningDialog!=null)learningDialog.dismiss();videoLoop.clear();if(loopDialog!=null)loopDialog.dismiss();if(momentDialog!=null)momentDialog.dismiss();subtitleGeneration++;clearSubtitle();}subtitleAttached=false;video.stop();current=item;now.setText(item.title);updateVideoLayout();
        // A document picker destroys the old Surface. Bind a fresh window after stopping,
        // so software decoders wait for the new Surface instead of producing audio only.
        video.detachViews();video.attachViews(surface,null,true,false);pendingSeek=Math.max(0,startPosition);
        closeDescriptor();software=useSoftware;adapter.notifyDataSetChanged();
        try{
            descriptor=getContentResolver().openFileDescriptor(item.uri,"r");if(descriptor==null)throw new java.io.IOException("Arquivo indisponível");
            Media media=new Media(engine,descriptor.getFileDescriptor());try{media.setHWDecoderEnabled(!useSoftware,false);video.setMedia(media);}finally{media.release();}
            ShelfStore.remember(this,"video",item.uri.toString(),item.title,startPosition,Math.max(item.duration,video.getLength()));playRequested=true;video.play();handler.postDelayed(firstFrameCheck,8000);status.setText(useSoftware?"Reproduzindo com decoder de software":"Abrindo vídeo…");
        }catch(Exception e){playRequested=false;abandonFocus();status.setText("Não foi possível abrir o vídeo. O arquivo pode ter sido removido ou o acesso expirou.");Toast.makeText(this,"Tente selecionar o arquivo novamente.",Toast.LENGTH_LONG).show();closeDescriptor();}
    }
    private void choose(VideoStore.Item item){
        disableLoop(null);
        search.clearFocus();root.requestFocus();android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(search.getWindowToken(),0);
        if(video!=null&&video.isPlaying())pauseVideo();long saved=VideoProgressStore.read(this,item.uri,item.duration);
        if(saved<=0){open(item,false);return;}if(resumeDialog!=null)resumeDialog.dismiss();
        resumeDialog=new AlertDialog.Builder(this).setTitle("Continuar vídeo?").setMessage(item.title+"\nContinuar de "+VideoText.duration(saved)+"?")
            .setPositiveButton("Continuar",(d,w)->open(item,false,saved)).setNeutralButton("Recomeçar",(d,w)->{open(item,false);VideoProgressStore.clear(this,item.uri);}).setNegativeButton("Cancelar",null).show();
    }
    private void remember(){if(!handedOff&&resumePosition<0&&video!=null&&current!=null&&video.getLength()>0)VideoProgressStore.save(this,current.uri,Math.max(0,video.getTime()),video.getLength());}
    private boolean applyPendingSeek(){
        // Seeking before the input clock starts can stall MPEG-TS playback.
        if(pendingSeek>0&&framesSeen&&video!=null&&video.isSeekable()&&video.getLength()>0&&video.getTime()>0){
            long target=Math.min(pendingSeek,Math.max(0,video.getLength()-500));pendingSeek=0;
            if(target>0){if(Math.abs(target-video.getTime())>1000)video.setTime(target);android.util.Log.d("OndaVideo","resumed "+target);return true;}
        }return false;
    }
    private void applyVideoVolume(){if(video!=null)video.setVolume(ducked?Math.round(videoVolume*.25f):videoVolume);}
    private void clearSubtitle(){captionsOff=false;subtitleEnabled=false;subtitleAttached=false;subtitleName="";if(subtitleFile!=null){subtitleFile.delete();subtitleFile=null;}}
    private void attachSubtitle(){if(video!=null&&captionsOff){if(!subtitleAttached){video.setSpuTrack(-1);subtitleAttached=true;}return;}if(video==null||!subtitleEnabled||subtitleAttached||subtitleFile==null||!framesSeen||video.getTime()<=0)return;
        // The String overload takes a filesystem path, not a file:// URI.
        subtitleAttached=video.addSlave(Media.Slave.Type.Subtitle,subtitleFile.getAbsolutePath(),true);
        android.util.Log.d("OndaVideo","subtitle "+(subtitleAttached?"attached ":"failed ")+subtitleName);
        if(!subtitleAttached)Toast.makeText(this,"Não foi possível ativar a legenda. Tente outro arquivo.",Toast.LENGTH_LONG).show();
    }
    private void subtitles(){if(current==null){Toast.makeText(this,"Abra um vídeo primeiro.",Toast.LENGTH_SHORT).show();return;}
        new AlertDialog.Builder(this).setTitle("Legendas do vídeo").setMessage((subtitleEnabled?"Arquivo: "+subtitleName:"Nenhuma legenda externa ativa")+"\nSRT, VTT, ASS e SSA, até 2 MB. A legenda fica disponível nesta sessão do vídeo.")
            .setPositiveButton("Abrir legenda",(d,w)->{subtitleWasPlaying=video!=null&&video.isPlaying();Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI,android.provider.DocumentsContract.buildDocumentUri("com.android.externalstorage.documents","primary:Download"));try{leavingForPicker=true;startActivityForResult(intent,SUBTITLE);}catch(ActivityNotFoundException e){leavingForPicker=false;Toast.makeText(this,"Seletor de arquivos indisponível.",Toast.LENGTH_LONG).show();}})
            .setNeutralButton("Desativar",(d,w)->{if(video!=null)video.setSpuTrack(-1);captionsOff=true;subtitleAttached=true;subtitleEnabled=false;Toast.makeText(this,"Legenda desativada",Toast.LENGTH_SHORT).show();}).setNegativeButton("Fechar",null).show();
    }
    private void loadSubtitle(Uri uri){if(current==null)return;Uri owner=current.uri;String name=selected(uri).file;String lower=name.toLowerCase(Locale.ROOT);String suffix=null;for(String ext:new String[]{".srt",".vtt",".ass",".ssa"})if(lower.endsWith(ext)){suffix=ext;break;}
        if(suffix==null){Toast.makeText(this,"Escolha uma legenda SRT, VTT, ASS ou SSA.",Toast.LENGTH_LONG).show();return;}
        int request=++subtitleGeneration;String extension=suffix;status.setText("Carregando legenda…");
        scanner.execute(()->{java.io.File copy=null;try{copy=java.io.File.createTempFile("onda-sub-",extension,getCacheDir());try(java.io.InputStream in=getContentResolver().openInputStream(uri);java.io.OutputStream out=new java.io.FileOutputStream(copy)){if(in==null)throw new java.io.IOException();byte[] bytes=new byte[8192];int n,total=0;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted()||(total+=n)>2*1024*1024)throw new java.io.IOException();out.write(bytes,0,n);}}java.io.File ready=copy;
            runOnUiThread(()->{if(isDestroyed()||request!=subtitleGeneration||current==null||!owner.equals(current.uri)){ready.delete();return;}clearSubtitle();subtitleFile=ready;subtitleName=name;subtitleEnabled=true;if(video.isPlaying())attachSubtitle();else if(subtitleWasPlaying&&started)resumeVideo();Toast.makeText(this,"Legenda carregada",Toast.LENGTH_SHORT).show();});
        }catch(Exception e){if(copy!=null)copy.delete();runOnUiThread(()->{if(!isDestroyed()&&request==subtitleGeneration)Toast.makeText(this,"Não foi possível ler a legenda. Verifique o arquivo e o limite de 2 MB.",Toast.LENGTH_LONG).show();});}});
    }
    private void disableLoop(String message){boolean was=videoLoop.active();videoLoop.clear();if(position!=null)update();if(was&&message!=null)Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
    private void checkLoop(boolean ended){if(!started||!playRequested||video==null||current==null||!videoLoop.active()||(!ended&&(!video.isPlaying()||!framesSeen||seeking||pendingSeek>0)))return;long time=video.getTime();boolean waiting=videoLoop.waiting();long target=ended?videoLoop.atEnd(SystemClock.elapsedRealtime()):videoLoop.correct(time,SystemClock.elapsedRealtime());if(target==VideoLoop.DONE){pauseVideo();video.setTime(Math.min(videoLoop.end(),Math.max(0,video.getLength()-1)));android.util.Log.d("OndaLearn","completed "+videoLoop.completed());Toast.makeText(this,"Trecho concluído "+videoLoop.completed()+" vezes",Toast.LENGTH_LONG).show();return;}if(target==VideoLoop.FAILED){android.util.Log.d("OndaLoop","failed");pauseVideo();Toast.makeText(this,"A repetição foi desativada porque este arquivo não respondeu à busca.",Toast.LENGTH_LONG).show();return;}if(target>=0){android.util.Log.d("OndaLoop","return "+target);if(ended)open(current,software,target);else video.setTime(target);}else if(waiting&&!videoLoop.waiting()&&videoLoop.active())android.util.Log.d("OndaLoop","reached "+time);}
    private void loopSettings(){if(video==null||current==null||!framesSeen||!video.isSeekable()||video.getLength()<2000){Toast.makeText(this,"Abra um vídeo de pelo menos 2 segundos primeiro.",Toast.LENGTH_SHORT).show();return;}Uri owner=current.uri;pauseVideo();long duration=video.getLength(),start=videoLoop.active()?videoLoop.start():Math.min(Math.max(0,video.getTime()/1000*1000),Math.max(0,duration/1000*1000-2000)),end=videoLoop.active()?videoLoop.end():Math.min(duration/1000*1000,start+10000);
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(Ui.dp(this,20),Ui.dp(this,10),Ui.dp(this,20),0);TextView info=Ui.text(this,"Use segundos, m:ss ou h:mm:ss. Mínimo de 2 segundos. Após ativar, toque em Reproduzir. Vale apenas nesta sessão do vídeo.",13,Ui.MUTED);info.setPadding(0,0,0,Ui.dp(this,10));box.addView(info);TextView aLabel=Ui.text(this,"Início (A)",13,Ui.CYAN);box.addView(aLabel);EditText a=new EditText(this);Ui.input(a);a.setContentDescription("Início do trecho A");a.setText(VideoLoop.time(start));a.setFilters(new InputFilter[]{new InputFilter.LengthFilter(16)});box.addView(a,new LinearLayout.LayoutParams(-1,-2));TextView bLabel=Ui.text(this,"Fim (B)",13,Ui.CYAN);bLabel.setPadding(0,Ui.dp(this,10),0,0);box.addView(bLabel);EditText b=new EditText(this);Ui.input(b);b.setContentDescription("Fim do trecho B");b.setText(VideoLoop.time(end));b.setFilters(new InputFilter[]{new InputFilter.LengthFilter(16)});box.addView(b,new LinearLayout.LayoutParams(-1,-2));TextView countLabel=Ui.text(this,"Quantidade de reproduções",13,Ui.CYAN);countLabel.setPadding(0,Ui.dp(this,10),0,0);box.addView(countLabel);Spinner count=new Spinner(this);count.setContentDescription("Quantidade de repetições do trecho");count.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Sem limite","3 vezes","5 vezes","10 vezes"}));int[] counts={0,3,5,10};int selected=0;for(int i=0;i<counts.length;i++)if(counts[i]==videoLoop.limit())selected=i;count.setSelection(selected);box.addView(count,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));ScrollView scrolling=new ScrollView(this);scrolling.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Repetir trecho A–B").setView(scrolling).setPositiveButton("Ativar",null).setNeutralButton("Desativar",(d,w)->disableLoop("Repetição desativada")).setNegativeButton("Cancelar",null).create();loopDialog=dialog;dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setEnabled(videoLoop.active());dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(!momentOwner(owner)){dialog.dismiss();return;}long from=VideoLoop.parse(a.getText().toString()),to=VideoLoop.parse(b.getText().toString());if(from<0){a.setError("Use segundos, m:ss ou h:mm:ss.");return;}if(to<0||!videoLoop.arm(from,to,video.getLength(),counts[count.getSelectedItemPosition()])){b.setError("O fim deve ficar pelo menos 2 segundos após o início e dentro do vídeo.");return;}update();dialog.dismiss();Toast.makeText(this,"Trecho preparado. Toque em Reproduzir.",Toast.LENGTH_SHORT).show();});});dialog.show();}
    private void learning(){if(video==null||current==null){Toast.makeText(this,"Abra um vídeo para usar o Modo Aprender.",Toast.LENGTH_SHORT).show();return;}pauseVideo();learningDialog=new AlertDialog.Builder(this).setTitle("Modo Aprender").setItems(new String[]{"Velocidade: "+rateLabel(),"Repetir trecho por quantidade","Anotações nos momentos salvos"},(d,i)->{if(i==0)speedSettings();else if(i==1)loopSettings();else showMoments();}).setNegativeButton("Fechar",null).show();}
    private String rateLabel(){return String.format(java.util.Locale.ROOT,"%.2f×",learningRate).replace(".00","").replace(".50",",5").replace(".25",",25").replace(".75",",75");}
    private void speedSettings(){float[] speeds={.5f,.75f,1f,1.25f,1.5f,2f};String[] labels={"0,5×","0,75×","1× • normal","1,25×","1,5×","2×"};int selected=2;for(int i=0;i<speeds.length;i++)if(speeds[i]==learningRate)selected=i;learningDialog=new AlertDialog.Builder(this).setTitle("Velocidade do vídeo").setSingleChoiceItems(labels,selected,(d,i)->{learningRate=speeds[i];video.setRate(learningRate);android.util.Log.d("OndaLearn","rate "+video.getRate());update();d.dismiss();Toast.makeText(this,"Velocidade "+rateLabel()+". Toque em Reproduzir.",Toast.LENGTH_SHORT).show();}).setNegativeButton("Cancelar",null).show();}
    private void editNote(Uri owner,VideoMoments.Moment item){if(!momentOwner(owner))return;EditText text=new EditText(this);Ui.input(text);text.setSingleLine(false);text.setMinLines(3);text.setMaxLines(6);text.setGravity(Gravity.TOP);text.setHint("Escreva sua anotação");text.setContentDescription("Anotação do momento");text.setFilters(new InputFilter[]{new InputFilter.LengthFilter(VideoMoments.NOTE_LIMIT)});text.setText(item.note);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(Ui.dp(this,20),Ui.dp(this,12),Ui.dp(this,20),0);TextView info=Ui.text(this,item.label+" • "+momentTime(item.position)+"\nAté 1.000 caracteres. Salva somente no celular; não altera o vídeo.",13,Ui.MUTED);box.addView(info);box.addView(text,new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(this);scroll.addView(box);momentDialog=new AlertDialog.Builder(this).setTitle("Anotação do momento").setView(scroll).setPositiveButton("Salvar",(d,w)->{if(momentOwner(owner)){boolean ok=VideoMomentStore.annotate(this,owner,item.id,text.getText().toString());Toast.makeText(this,ok?"Anotação salva":"O momento não está mais disponível.",Toast.LENGTH_SHORT).show();}}).setNegativeButton("Cancelar",null).show();}
    private String momentTime(long time){return time==0?"0:00":VideoText.duration(time);}
    private boolean momentOwner(Uri owner){if(current!=null&&current.uri.equals(owner))return true;Toast.makeText(this,"O vídeo mudou. Abra os momentos novamente.",Toast.LENGTH_SHORT).show();return false;}
    private void markMoment(){if(current==null||video==null||!framesSeen||!video.isSeekable()||video.getLength()<=0){Toast.makeText(this,"Reproduza um vídeo antes de marcar um momento.",Toast.LENGTH_SHORT).show();return;}Uri owner=current.uri;long at=Math.max(0,Math.min(video.getTime(),video.getLength()-1));pauseVideo();editMoment(owner,null,at);}
    private void editMoment(Uri owner,VideoMoments.Moment existing,long at){if(!momentOwner(owner))return;EditText name=new EditText(this);Ui.input(name);name.setHint("Nome do momento");name.setContentDescription("Nome do momento do vídeo");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(VideoMoments.LABEL_LIMIT)});name.setText(existing==null?"Momento em "+momentTime(at):existing.label);name.selectAll();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(Ui.dp(this,20),Ui.dp(this,12),Ui.dp(this,20),0);TextView info=Ui.text(this,"Vídeo pausado • "+momentTime(at)+"\nDê um nome para encontrar este trecho depois.",13,Ui.MUTED);info.setPadding(0,0,0,Ui.dp(this,12));box.addView(info);box.addView(name,new LinearLayout.LayoutParams(-1,-2));
        momentDialog=new AlertDialog.Builder(this).setTitle(existing==null?"Marcar momento":"Renomear momento").setView(box).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();momentDialog.setOnShowListener(d->momentDialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(!momentOwner(owner)){momentDialog.dismiss();return;}String label=VideoMoments.label(name.getText().toString());if(label.isEmpty()){name.setError("Digite um nome para o momento.");return;}boolean ok=existing==null?VideoMomentStore.add(this,owner,label,at)!=null:VideoMomentStore.rename(this,owner,existing.id,label);if(!ok){name.setError("Não foi possível salvar. Limite de 30 momentos por vídeo e 100 vídeos.");return;}Toast.makeText(this,"Momento salvo",Toast.LENGTH_SHORT).show();momentDialog.dismiss();}));momentDialog.show();}
    private void showMoments(){if(current==null||video==null){Toast.makeText(this,"Escolha um vídeo primeiro.",Toast.LENGTH_SHORT).show();return;}Uri owner=current.uri;pauseVideo();List<VideoMoments.Moment> saved=VideoMomentStore.read(this,owner);if(saved.isEmpty()){momentDialog=new AlertDialog.Builder(this).setTitle("Momentos salvos").setMessage("Este vídeo ainda não tem momentos. Use Menu → Marcar momento para guardar uma cena.").setPositiveButton("Entendi",null).show();return;}String[] labels=new String[saved.size()];for(int i=0;i<saved.size();i++)labels[i]=momentTime(saved.get(i).position)+" • "+saved.get(i).label;momentDialog=new AlertDialog.Builder(this).setTitle("Momentos deste vídeo").setItems(labels,(d,i)->momentOptions(owner,saved.get(i))).setNegativeButton("Fechar",null).show();}
    private void momentOptions(Uri owner,VideoMoments.Moment item){if(!momentOwner(owner))return;momentDialog=new AlertDialog.Builder(this).setTitle(item.label+" • "+momentTime(item.position)).setItems(new String[]{"Reproduzir daqui","Renomear","Excluir","Anotação"},(d,i)->{if(!momentOwner(owner))return;if(i==0){if(VideoMomentStore.read(this,owner).stream().noneMatch(m->m.id.equals(item.id))){Toast.makeText(this,"Este momento já foi removido.",Toast.LENGTH_SHORT).show();return;}disableLoop(null);android.util.Log.d("OndaMoments","requested "+item.position);open(current,software,item.position);}else if(i==1)editMoment(owner,item,item.position);else if(i==3)editNote(owner,item);else momentDialog=new AlertDialog.Builder(this).setTitle("Excluir momento?").setMessage("Apenas a marcação será removida. O vídeo continua no celular.").setPositiveButton("Excluir",(a,b)->{if(momentOwner(owner)){VideoMomentStore.remove(this,owner,item.id);Toast.makeText(this,"Momento excluído",Toast.LENGTH_SHORT).show();}}).setNegativeButton("Cancelar",null).show();}).setNegativeButton("Cancelar",null).show();}
    private void gestureHelp(){new AlertDialog.Builder(this).setTitle("Gestos e posição").setMessage("Na área do vídeo, deslize para cima ou para baixo:\n\nEsquerda: brilho apenas desta tela.\nDireita: volume apenas do vídeo no Onda.\n\nA posição é salva ao pausar, trocar de vídeo ou sair. Ao abrir novamente, escolha Continuar ou Recomeçar. Vídeos terminados voltam ao início. O botão CC abre legendas externas. Em tela cheia, toque na imagem para mostrar ou ocultar os controles; eles somem após alguns segundos durante a reprodução.").setPositiveButton("Entendi",null).setNeutralButton("Restaurar ajustes",(d,w)->{WindowManager.LayoutParams a=getWindow().getAttributes();a.screenBrightness=-1;getWindow().setAttributes(a);videoVolume=100;applyVideoVolume();getSharedPreferences("video_controls",0).edit().putInt("volume",100).apply();}).show();}
    private void setupGestures(){gestureLayer.setOnClickListener(v->{if(current!=null){if(fullscreen)setVideoControlsVisible(!videoControlsVisible);else showGesture("Esquerda: brilho • Direita: volume");}});gestureLayer.setOnTouchListener(new View.OnTouchListener(){float x,y,startBrightness;int startVolume;boolean changed,left;
        public boolean onTouch(View v,MotionEvent e){if(current==null||video==null)return false;switch(e.getActionMasked()){
            case MotionEvent.ACTION_DOWN:x=e.getX();y=e.getY();changed=false;left=x<v.getWidth()/2f;startVolume=videoVolume;startBrightness=getWindow().getAttributes().screenBrightness;if(startBrightness<0)try{startBrightness=android.provider.Settings.System.getInt(getContentResolver(),android.provider.Settings.System.SCREEN_BRIGHTNESS)/255f;}catch(Exception ex){startBrightness=.5f;}return true;
            case MotionEvent.ACTION_MOVE:float delta=y-e.getY();if(!changed&&(Math.abs(delta)<Ui.dp(VideoActivity.this,12)||Math.abs(delta)<Math.abs(x-e.getX())))return true;changed=true;float fraction=delta/Math.max(1,v.getHeight());if(left){WindowManager.LayoutParams attributes=getWindow().getAttributes();attributes.screenBrightness=VideoProgress.brightness(startBrightness,fraction);getWindow().setAttributes(attributes);showGesture("Brilho "+Math.round(attributes.screenBrightness*100)+"%");}else{videoVolume=VideoProgress.volume(startVolume,fraction);applyVideoVolume();showGesture("Volume "+videoVolume+"%");}return true;
            case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:if(changed){getSharedPreferences("video_controls",0).edit().putInt("volume",videoVolume).apply();android.util.Log.d("OndaVideo","gesture "+(left?"brightness "+getWindow().getAttributes().screenBrightness:"volume "+videoVolume));}else if(e.getActionMasked()==MotionEvent.ACTION_UP)v.performClick();return true;
            default:return true;
        }} });}
    private void showGesture(String text){gestureFeedback.setText(text);gestureFeedback.setVisibility(View.VISIBLE);handler.removeCallbacks(hideGesture);handler.postDelayed(hideGesture,1200);}
    private boolean requestFocus(){if(audio==null||focus==null)return false;hasFocus=audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;if(hasFocus){ducked=false;applyVideoVolume();}if(!hasFocus)Toast.makeText(this,"Áudio ocupado. Tente novamente.",Toast.LENGTH_SHORT).show();return hasFocus;}
    private void abandonFocus(){if(audio!=null&&focus!=null)audio.abandonAudioFocusRequest(focus);hasFocus=false;}
    private void resumeVideo(){if(video==null||current==null||!started||music==null)return;long at=resumePosition>=0?resumePosition:Math.max(0,video.getTime()),length=resumePosition>=0?resumeDuration:video.getLength();if(videoLoop.active()&&(at<videoLoop.start()||at>=videoLoop.end()))at=videoLoop.start();open(current,software,!videoLoop.active()&&length>0&&at>=length-500?0:at);}
    private void pauseVideo(){playRequested=false;handler.removeCallbacks(hideVideoControls);handler.removeCallbacks(firstFrameCheck);remember();if(video!=null){video.pause();android.util.Log.d("OndaVideo","paused at "+Math.max(0,video.getTime()));}handler.removeCallbacks(tick);getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);abandonFocus();if(fullscreen&&!isInPictureInPictureMode())setVideoControlsVisible(true);else update();if(adapter!=null)adapter.notifyDataSetChanged();}
    private void update(){if(video==null)return;boolean playing=video.isPlaying();play.setText(playing?"❚❚":"▶");play.setContentDescription(playing?"Pausar vídeo":"Reproduzir vídeo");long length=resumePosition>=0?resumeDuration:Math.max(0,video.getLength()),time=resumePosition>=0?resumePosition:Math.max(0,video.getTime());if(!seeking)seek.setProgress(length>0?(int)Math.min(1000,time*1000/length):0);seek.setEnabled(resumePosition>=0?resumeDuration>0:video.isSeekable());position.setText(VideoText.duration(time)+" / "+VideoText.duration(length)+(videoLoop.active()?"\nA–B • "+VideoLoop.time(videoLoop.start())+" → "+VideoLoop.time(videoLoop.end())+(videoLoop.limit()>0?" • "+videoLoop.completed()+"/"+videoLoop.limit():""):""));if(started&&playing)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
    private void restartTick(){handler.removeCallbacks(tick);if(started&&!isInPictureInPictureMode()&&(!fullscreen||videoControlsVisible))handler.post(tick);}
    private void setFullscreen(boolean value){fullscreen=value;videoControlsVisible=true;handler.removeCallbacks(hideVideoControls);updateVideoLayout();full.setText(value?"Voltar":"Tela cheia");full.setContentDescription(value?"Sair da tela cheia":"Tela cheia do vídeo");getWindow().getDecorView().setSystemUiVisibility(value?View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE:View.SYSTEM_UI_FLAG_LAYOUT_STABLE);setRequestedOrientation(value?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);root.requestApplyInsets();restartTick();scheduleControlsHide();}
    private PictureInPictureParams pipParams(){
        boolean playing=video!=null&&video.isPlaying();Intent intent=new Intent(PIP_ACTION).setPackage(getPackageName());PendingIntent pending=PendingIntent.getBroadcast(this,731,intent,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);
        RemoteAction toggle=new RemoteAction(android.graphics.drawable.Icon.createWithResource(this,playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play),playing?"Pausar":"Reproduzir",playing?"Pausar vídeo":"Reproduzir vídeo",pending);
        return new PictureInPictureParams.Builder().setAspectRatio(new android.util.Rational(16,9)).setActions(Collections.singletonList(toggle)).build();
    }
    private void updatePipActions(){if(isInPictureInPictureMode())setPictureInPictureParams(pipParams());}
    private void enterFloating(){
        if(!getPackageManager().hasSystemFeature(PackageManager.FEATURE_PICTURE_IN_PICTURE)){Toast.makeText(this,"Este aparelho não oferece janela flutuante.",Toast.LENGTH_LONG).show();return;}
        if(video==null||current==null||!video.isPlaying()){Toast.makeText(this,"Reproduza um vídeo primeiro.",Toast.LENGTH_SHORT).show();return;}
        try{enteringPip=true;if(!enterPictureInPictureMode(pipParams())){enteringPip=false;Toast.makeText(this,"Permita imagem em imagem para o Onda nas configurações do Android.",Toast.LENGTH_LONG).show();}}catch(IllegalStateException|IllegalArgumentException e){enteringPip=false;Toast.makeText(this,"Não foi possível abrir a janela flutuante. Confira a permissão de imagem em imagem do Onda.",Toast.LENGTH_LONG).show();}
    }
    @Override public void onPictureInPictureModeChanged(boolean active,android.content.res.Configuration config){super.onPictureInPictureModeChanged(active,config);enteringPip=false;
        android.util.Log.d("OndaVideo","pip "+active);
        if(active){handler.removeCallbacks(hideVideoControls);handler.removeCallbacks(tick);heading.setVisibility(View.GONE);now.setVisibility(View.GONE);browser.setVisibility(View.GONE);navigation.setVisibility(View.GONE);transport.setVisibility(View.GONE);gestureLayer.setVisibility(View.GONE);gestureFeedback.setVisibility(View.GONE);surfaceBox.setVisibility(View.VISIBLE);surfaceBox.setLayoutParams(new LinearLayout.LayoutParams(-1,0,1));root.requestApplyInsets();}
        else{gestureLayer.setVisibility(View.VISIBLE);setFullscreen(fullscreen);}
    }
    @Override public void onBackPressed(){if(fullscreen)setFullscreen(false);else super.onBackPressed();}
    private void about(){new AlertDialog.Builder(this).setTitle("Motor de vídeo LibVLC").setMessage("Suporte amplo a MP4, MKV, AVI, MOV, WebM, FLV, WMV, MPEG, TS e outros contêineres. A compatibilidade depende dos codecs, do aparelho e do arquivo. Conteúdo com DRM não é suportado.\n\nLibVLC 3.7.7 © VideoLAN e colaboradores, LGPL 2.1 ou posterior. Bibliotecas nativas sem modificações; fonte e instruções de compilação em code.videolan.org/videolan/libvlcjni. O APK inclui a licença em assets/libvlc-license.txt.\n\nUse Menu → Janela flutuante para continuar assistindo em outros aplicativos. Ative Reprodução em segundo plano para continuar ouvindo o áudio ao sair da tela ou bloquear o celular. A passagem entre a tela e o áudio pode ter uma breve pausa. A disponibilidade depende do Android e das permissões do aparelho.").setPositiveButton("OK",null).setNeutralButton("Licença",(d,w)->showLicense()).show();}
    private void showLicense(){try(java.io.InputStream input=getAssets().open("libvlc-license.txt")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=input.read(buf))!=-1)out.write(buf,0,n);TextView text=Ui.text(this,out.toString("UTF-8"),12,Ui.TEXT);text.setPadding(24,24,24,24);ScrollView scroll=new ScrollView(this);scroll.addView(text);new AlertDialog.Builder(this).setTitle("LibVLC • LGPL 2.1").setView(scroll).setPositiveButton("Fechar",null).show();}catch(Exception e){Toast.makeText(this,"Licença indisponível.",Toast.LENGTH_SHORT).show();}}
    private void closeDescriptor(){if(descriptor!=null){try{descriptor.close();}catch(java.io.IOException ignored){}descriptor=null;}}
    private void backgroundSettings(){new AlertDialog.Builder(this).setTitle("Reprodução em segundo plano").setSingleChoiceItems(new String[]{"Pausar ao sair","Continuar áudio"},getSharedPreferences("video_controls",0).getBoolean("background",true)?1:0,(d,w)->{getSharedPreferences("video_controls",0).edit().putBoolean("background",w==1).apply();d.dismiss();}).setNegativeButton("Fechar",null).show();}
    private void restoreBackground(){VideoBackgroundService.Snapshot s=backgroundRestore;backgroundRestore=null;handedOff=false;VideoStore.Item item=new VideoStore.Item(s.uri,s.title,s.file,s.duration,0);current=item;now.setText(s.title);learningRate=s.rate;videoVolume=s.volume;software=s.software;videoLoop=s.loop==null?new VideoLoop():s.loop;videoLoop.continuePlayback();if(s.playing){open(item,s.software,s.position);}else{resumePosition=s.position;resumeDuration=s.duration;playRequested=false;updateVideoLayout();update();status.setText("Vídeo pausado • toque em Reproduzir para continuar");}}
    @Override protected void onStart(){super.onStart();started=true;
        if(VideoBackgroundService.active()){backgroundRestore=VideoBackgroundService.take(this);pending=null;}
        else if(handedOff&&current!=null){resumePosition=VideoProgressStore.read(this,current.uri,current.duration);resumeDuration=Math.max(resumeDuration,current.duration);handedOff=false;}
        update();openPending();}
    @Override protected void onPause(){
        if(!isFinishing()&&!isChangingConfigurations()&&!leavingForPicker&&!enteringPip&&!isInPictureInPictureMode()&&!handedOff&&video!=null&&current!=null&&playRequested&&video.isPlaying()&&getSharedPreferences("video_controls",0).getBoolean("background",true)){
            VideoBackgroundService.Snapshot snapshot=new VideoBackgroundService.Snapshot(current.uri,current.title,current.file,Math.max(pendingSeek,Math.max(0,video.getTime())),video.getLength(),learningRate,videoVolume,software,videoLoop,true);
            pauseVideo();try{VideoBackgroundService.start(this,snapshot);handedOff=true;resumeDuration=snapshot.duration;android.util.Log.d("OndaVideoBg","handoff "+snapshot.position);}catch(RuntimeException e){status.setText("Não foi possível continuar em segundo plano. Abra o vídeo novamente.");}
        }
        super.onPause();
    }
    @Override protected void onResume(){super.onResume();if(search!=null&&allowed())scan();}
    @Override protected void onStop(){started=false;pending=null;pendingPosition=-1;if(momentDialog!=null)momentDialog.dismiss();if(loopDialog!=null)loopDialog.dismiss();if(learningDialog!=null)learningDialog.dismiss();if(!handedOff)pauseVideo();super.onStop();}
    @Override public void onDestroy(){subtitleGeneration++;if(resumeDialog!=null)resumeDialog.dismiss();if(momentDialog!=null)momentDialog.dismiss();if(loopDialog!=null)loopDialog.dismiss();if(learningDialog!=null)learningDialog.dismiss();clearSubtitle();handler.removeCallbacksAndMessages(null);scanner.shutdownNow();if(receiverRegistered)unregisterReceiver(noisy);if(pipReceiverRegistered)unregisterReceiver(pipControls);abandonFocus();if(video!=null){video.setEventListener(null);video.stop();video.detachViews();video.release();}closeDescriptor();if(engine!=null)engine.release();if(connection!=null)MediaController.releaseFuture(connection);super.onDestroy();}
